fn format_count(cb_str: &str, offset_str: &str, actual: i64) -> String {
    let cb: f64 = cb_str.parse().unwrap();
    let offset: f64 = offset_str.parse().unwrap();
    let count = offset + cb * (actual as f64);
    // determine precision from cb_str
    let prec = if cb_str.contains('.') {
        cb_str.split('.').nth(1).unwrap().len()
    } else {
        0
    };
    if prec==0 {
        format!("{:.0}", count)
    } else {
        format!("{:.*}", prec, count)
    }
}

fn main(){
    let tests = [
        ("0.5","0.05",0),
        ("1.0","0.05",0),
        ("0.5","0.05",1),
