        println!("cb={} off={} actual={} => {}", cb, off, actual, format_count(cb, off, actual));
    }
    // also test with f32
    println!("--- f32 version");
    for (cb_str, off_str, actual) in tests {
        let cb: f32 = cb_str.parse().unwrap();
