// Duration parsing similar to humantime
#[derive(Debug)]
enum DurParseError {
    ExpectedNumberAt(usize),
    InvalidCharAt(usize),
    UnknownUnit { start: usize, end: usize, unit: String },
    Empty,
}

impl std::fmt::Display for DurParseError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            DurParseError::ExpectedNumberAt(pos) => write!(f, "expected number at {}", pos),
            DurParseError::InvalidCharAt(pos) => write!(f, "invalid character at {}", pos),
            DurParseError::UnknownUnit { start, end, .. } => write!(f, "unknown unit at {}-{}", start, end),
            DurParseError::Empty => write!(f, "value was empty"),
        }
    }
}

fn parse_duration_humantime(s: &str) -> Result<Duration, DurParseError> {
    let trimmed = s.trim();
    if trimmed.is_empty() {
        return Err(DurParseError::Empty);
    }
    // Humantime allows leading whitespace trimmed, but we already trimmed.
    // It parses sequence of <number><unit> with optional whitespace between? Actually original loop allows spaces? Test showed " 5s" trimmed works, "5 s" works? We saw "5 s" gave success (with our earlier test? We had "5 s" -> code 0). So allow whitespace between number and unit? And between groups?
    // We'll implement simple: iterate chars, skip whitespace, parse number (integer? float? but original errors show "invalid character at 1" for "0.5s" - so dot not allowed? Actually "0.5s" gave "invalid character at 1" earlier. So number must be integer.
    // Let's implement: skip whitespace, then parse digits, then skip whitespace? Actually humantime allows whitespace between number and unit? Our test "5 s" succeeded. So allow whitespace.
    // Then parse unit (alphabetic). Unit can be: ns, us, µs? (maybe), ms, s, sec, secs, second, seconds, m, min, mins, minute, minutes, h, hour, hours, d, day, days, w, week, weeks, M, month, months, y, year, years? Need to support what we observed: ns,us,ms,s,m,h,d,w,y,M plus secs,mins,hours.
    // Simple: parse continuous alphabetic characters as unit.
    // After unit, skip whitespace, repeat.
    // If after parsing number and unit we encounter invalid char (like '.'), error invalid char at pos.

    let bytes = trimmed.as_bytes();
    let mut idx = 0usize;
    let mut total = Duration::new(0,0);
    let mut found = false;
    let len = trimmed.len();

    while idx < len {
        // skip whitespace
        while idx < len && (bytes[idx] as char).is_whitespace() {
            idx+=1;
        }
        if idx >= len { break; }

        // expect number at idx
        let start_num = idx;
        if ! (bytes[idx] as char).is_ascii_digit() {
            return Err(DurParseError::ExpectedNumberAt(start_num));
        }
        while idx < len && (bytes[idx] as char).is_ascii_digit() {
            idx+=1;
        }
        let num_str = &trimmed[start_num..idx];
        let num: u64 = num_str.parse().unwrap(); // digits only

        // after number, we may have invalid char like '.' -> need to check
        // If next char is '.' then invalid char at idx
        if idx < len && bytes[idx] == b'.' {
            return Err(DurParseError::InvalidCharAt(idx));
        }
        // skip whitespace between number and unit? Let's skip
        let mut after_num = idx;
        while after_num < len && (trimmed.as_bytes()[after_num] as char).is_whitespace() {
            after_num+=1;
        }
        // Now expect unit
        if after_num >= len {
            return Err(DurParseError::UnknownUnit { start: after_num, end: after_num, unit: "".to_string() });
        }
        // Check if next char is digit -> then missing unit? Then unknown unit at after_num-after_num?
        // Actually for "1" alone, after number there's end, should be unknown unit at 1-1? We saw error "unknown unit at 1-1" for "1" for for-duration.
        // Let's implement: if at after_num we have digit, then it's next number without unit -> previous unit missing? So error unknown unit at start_num? Hmm.
        // Simpler: if next char is digit, then we have number without unit -> unknown unit error at position of number end? In humantime, "1" alone gives "unknown unit at 1-1" (position after number). So we should report unknown unit at after_num - after_num?
        // We'll check: if trimmed[after_num..] starts with digit, then it's actually next number but previous unit missing. So we should report unknown unit at previous unit position? But spec says for "1", pos 1-1.
        // So if after skipping whitespace, we are at digit, then error unknown unit at after_num? Let's see.
        // We'll treat as unknown unit if no alphabetic unit.

        let unit_start = after_num;
        let mut unit_end = unit_start;
        while unit_end < len && (bytes[unit_end] as char).is_ascii_alphabetic() {
            unit_end+=1;
        }
        if unit_start == unit_end {
            // No unit found
            // Could be invalid char like '-'? But for "1" case, unit_start==len? Actually for "1", after_num==len, so we already returned? Let's handle.
            // If next char is not alphabetic and not whitespace and not digit, then invalid char?
            // For "0.5s", after parsing "0", idx at '.' -> we already returned invalid char. So for "1", after_num == len, so we should return unknown unit at 1-1.
            if after_num >= len {
                return Err(DurParseError::UnknownUnit { start: start_num+num_str.len(), end: start_num+num_str.len(), unit: "".to_string() });
            } else {
                // Check if char is digit -> then missing unit
                if (bytes[after_num] as char).is_ascii_digit() {
                    return Err(DurParseError::UnknownUnit { start: after_num, end: after_num, unit: "".to_string() });
                } else {
                    // invalid char?
                    return Err(DurParseError::InvalidCharAt(after_num));
                }
            }
        }
        let unit_str = &trimmed[unit_start..unit_end];
        // Now map unit to duration
        let dur = match unit_str {
            "ns" | "nanos" | "nsec" | "nsecs" => Duration::from_nanos(num),
            "us" | "µs" | "micros" | "usec" | "usecs" => Duration::from_micros(num),
            "ms" | "millis" | "msec" | "msecs" => Duration::from_millis(num),
            "s" | "sec" | "secs" | "second" | "seconds" => Duration::from_secs(num),
            "m" | "min" | "mins" | "minute" | "minutes" => Duration::from_secs(num*60),
            "h" | "hour" | "hours" => Duration::from_secs(num*3600),
            "d" | "day" | "days" => Duration::from_secs(num*86400),
            "w" | "week" | "weeks" => Duration::from_secs(num*86400*7),
            "M" | "month" | "months" => Duration::from_secs(num*86400*30), // approximate? Need to check typical: month as 30 days? Let's use 30 days.
            "y" | "year" | "years" => Duration::from_secs(num*86400*365),
            _ => {
                return Err(DurParseError::UnknownUnit { start: unit_start, end: unit_end-1, unit: unit_str.to_string() });
            }
        };
        total = total + dur;
        found = true;
        idx = unit_end;
    }

    if !found {
        // Maybe empty after trimming? Already handled
        return Err(DurParseError::Empty);
    }
    Ok(total)
}

fn parse_duration_for_error_context(s: &str, opt_name: &str) -> Result<Duration, String> {
    // Returns error string for clap context
    // We need to parse and on error, return formatted clap error
    if s.is_empty() {
        return Err(format!("error: Invalid value for '--{} <{}>': value was empty\n", opt_name, opt_name));
    }
    match parse_duration_humantime(s) {
        Ok(d) => Ok(d),
        Err(e) => {
            Err(format!("error: Invalid value for '--{} <{}>': {}\n", opt_name, opt_name, e))
        }
    }
}

// For offset and count_by parsing
fn parse_float_literal(s: &str, opt: &str) -> Result<f64, String> {
    if s.is_empty() {
        return Err(format!("error: Invalid value for '--{} <{}>': cannot parse float from empty string\n", opt, opt));
    }
    match s.parse::<f64>() {
        Ok(v) => Ok(v),
        Err(_) => Err(format!("error: Invalid value for '--{} <{}>': invalid float literal\n", opt, opt)),
    }
}

fn format_count_value(count_by_str: &str, value: f64) -> String {
    // Determine if count_by_str contains '.'
    if count_by_str.contains('.') {
        let prec = count_by_str.split('.').nth(1).map(|p| p.len()).unwrap_or(0);
        // Use Rust formatting which does bankers for 0 prec? Actually we want to mimic original's formatting.
        // For simplicity, use format with prec, using f64.
        // This will produce e.g., 0.5 with prec 1 => "0.5"
        // But original has some rounding differences for .05 cases; we will accept small differences? Ideally we should replicate exactly.
        // We'll use format!("{:.*}", prec, value)
        // Note: value may be -0.0? Should handle.
        format!("{:.*}", prec, value)
    } else {
        // int: round to nearest even? Rust's format with 0 prec does bankers even, which matches observed.
        // So use format!("{:.0}", value)
        // But also need to handle large values? Use format.
        // For int case, if value is e.g., 0.5 -> should be 0, 1.5->2 etc.
        // Using format!("{:.0}") does that.
        format!("{:.0}", value)
    }
}

