#[derive(Debug)]
enum DurParseError {
    ExpectedNumberAt(usize),
    InvalidCharAt(usize),
    UnknownUnit { start: usize, end: usize },
    Empty,
}

impl std::fmt::Display for DurParseError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            DurParseError::ExpectedNumberAt(pos) => write!(f, "expected number at {}", pos),
            DurParseError::InvalidCharAt(pos) => write!(f, "invalid character at {}", pos),
            DurParseError::UnknownUnit { start, end } => write!(f, "unknown unit at {}-{}", start, end),
            DurParseError::Empty => write!(f, "value was empty"),
        }
    }
}

fn parse_duration_humantime(s: &str) -> Result<Duration, DurParseError> {
    let trimmed = s.trim();
    if trimmed.is_empty() {
        return Err(DurParseError::Empty);
    }
    let bytes = trimmed.as_bytes();
    let mut idx = 0usize;
    let mut total = Duration::new(0,0);
    let mut found = false;
    let len = trimmed.len();
    while idx < len {
        while idx < len && (bytes[idx] as char).is_whitespace() {
            idx+=1;
        }
        if idx >= len { break; }
        let start_num = idx;
        if ! (bytes[idx] as char).is_ascii_digit() {
            return Err(DurParseError::ExpectedNumberAt(start_num));
        }
        while idx < len && (bytes[idx] as char).is_ascii_digit() {
            idx+=1;
        }
        let num_str = &trimmed[start_num..idx];
        let num: u64 = num_str.parse().unwrap();
        if idx < len && bytes[idx] == b'.' {
            return Err(DurParseError::InvalidCharAt(idx));
        }
        let mut after_num = idx;
        while after_num < len && (trimmed.as_bytes()[after_num] as char).is_whitespace() {
            after_num+=1;
        }
        if after_num >= len {
            return Err(DurParseError::UnknownUnit { start: start_num+num_str.len(), end: start_num+num_str.len() });
        }
        if (bytes[after_num] as char).is_ascii_digit() {
            return Err(DurParseError::UnknownUnit { start: after_num, end: after_num });
        }
        if !(bytes[after_num] as char).is_ascii_alphabetic() {
            return Err(DurParseError::InvalidCharAt(after_num));
        }
        let unit_start = after_num;
        let mut unit_end = unit_start;
        while unit_end < len && (bytes[unit_end] as char).is_ascii_alphabetic() {
            unit_end+=1;
        }
        let unit_str = &trimmed[unit_start..unit_end];
        let dur = match unit_str {
            "ns" | "nanos" | "nsec" | "nsecs" => Duration::from_nanos(num),
            "us" | "µs" | "micros" | "usec" | "usecs" => Duration::from_micros(num),
            "ms" | "millis" | "msec" | "msecs" => Duration::from_millis(num),
            "s" | "sec" | "secs" | "second" | "seconds" => Duration::from_secs(num),
            "m" | "min" | "mins" | "minute" | "minutes" => Duration::from_secs(num*60),
            "h" | "hour" | "hours" => Duration::from_secs(num*3600),
            "d" | "day" | "days" => Duration::from_secs(num*86400),
            "w" | "week" | "weeks" => Duration::from_secs(num*86400*7),
            "M" | "month" | "months" => Duration::from_secs(num*86400*30),
            "y" | "year" | "years" => Duration::from_secs(num*86400*365),
            _ => {
                return Err(DurParseError::UnknownUnit { start: unit_start, end: unit_end-1 });
            }
        };
        total = total + dur;
        found = true;
        idx = unit_end;
    }
    if !found {
        return Err(DurParseError::Empty);
    }
    Ok(total)
}

fn parse_duration_for_error_context(s: &str, opt_name: &str) -> Result<Duration, String> {
    if s.is_empty() {
        return Err(format!("error: Invalid value for '--{} <{}>': value was empty\n", opt_name, opt_name));
    }
    match parse_duration_humantime(s) {
        Ok(d) => Ok(d),
        Err(e) => {
            Err(format!("error: Invalid value for '--{} <{}>': {}\n", opt_name, opt_name, e))
        }
    }
}

fn parse_float_literal(s: &str, opt: &str) -> Result<f64, String> {
    if s.is_empty() {
        return Err(format!("error: Invalid value for '--{} <{}>': cannot parse float from empty string\n", opt, opt));
    }
    match s.parse::<f64>() {
        Ok(v) => Ok(v),
        Err(_) => Err(format!("error: Invalid value for '--{} <{}>': invalid float literal\n", opt, opt)),
    }
}

fn format_count_value(count_by_str: &str, value: f64) -> String {
    if count_by_str.contains('.') {
        let prec = count_by_str.split('.').nth(1).map(|p| p.len()).unwrap_or(0);
        format!("{:.*}", prec, value)
    } else {
        format!("{:.0}", value)
    }
}

