                        Err(e) => { eprint!("{}", e); std::process::exit(1); }
                    }
                }
                "--until-contains" => {
                    let val = if let Some(v) = opt_val_opt { v } else { i+=1; if i>=args.len(){ eprint!("error: The argument '--until-contains <until_contains>' requires a value but none was supplied\n\nUSAGE:\n    executable [FLAGS] [OPTIONS] [input]...\n\nFor more information try --help\n"); std::process::exit(1);} args[i].clone() };
                    until_contains = Some(val);
                }
                "--until-error" => {
                    let val = if let Some(v) = opt_val_opt { v } else { i+=1; if i>=args.len(){ eprint!("error: The argument '--until-error <until_error>' requires a value but none was supplied\n\nUSAGE:\n    executable [FLAGS] [OPTIONS] [input]...\n\nFor more information try --help\n"); std::process::exit(1);} args[i].clone() };
                    let parsed = val.parse::<i32>().ok();
                    until_error = parsed;
                }
                "--until-match" => {
                    let val = if let Some(v) = opt_val_opt { v } else { i+=1; if i>=args.len(){ eprint!("error: The argument '--until-match <until_match>' requires a value but none was supplied\n\nUSAGE:\n    executable [FLAGS] [OPTIONS] [input]...\n\nFor more information try --help\n"); std::process::exit(1);} args[i].clone() };
                    match Regex::new(&val) {
                        Ok(re) => { until_match_regex = Some(re); }
                        Err(e) => { eprint!("error: Invalid value for '--until-match <until_match>': {}\n", e); std::process::exit(1); }
                    }
                }
                "--until-time" => {
                    let val = if let Some(v) = opt_val_opt { v } else { i+=1; if i>=args.len(){ eprint!("error: The argument '--until-time <until_time>' requires a value but none was supplied\n\nUSAGE:\n    executable [FLAGS] [OPTIONS] [input]...\n\nFor more information try --help\n"); std::process::exit(1);} args[i].clone() };
                    match NaiveDateTime::parse_from_str(&val, "%Y-%m-%d %H:%M:%S") {
                        Ok(ndt) => { until_time = Some(ndt); }
                        Err(_) => { eprint!("error: Invalid value for '--until-time <until_time>': timestamp format is invalid\n"); std::process::exit(1); }
                    }
                }
                _ => {
                    eprint!("error: Found argument '{}' which wasn't expected, or isn't valid in this context\n\nUSAGE:\n    executable [FLAGS] [OPTIONS] [input]...\n\nFor more information try --help\n", opt_name);
                    std::process::exit(1);
                }
            }
        } else if !stop_parsing && arg.starts_with("-") && arg.len()>1 {
            let chars: Vec<char> = arg[1..].chars().collect();
            let mut j = 0;
            while j < chars.len() {
                let ch = chars[j];
                match ch {
                    'h' => { help_flag = true; j+=1; }
                    'V' => { version_flag = true; j+=1; }
                    'D' => { error_duration = true; j+=1; }
                    'l' => { only_last = true; j+=1; }
                    'i' => { stdin_flag = true; j+=1; }
                    'C' => { until_changes = true; j+=1; }
                    'f' => { until_fail = true; j+=1; }
                    'S' => { until_same = true; j+=1; }
                    's' => { until_success = true; j+=1; }
                    'b' | 'e' | 'd' | 'n' | 'o' | 'c' | 'r' | 'm' | 't' => {
                        let opt_char = ch;
                        let remaining: String = chars[j+1..].iter().collect();
                        let val: String;
                        if !remaining.is_empty() {
                            val = remaining;
                            j = chars.len();
                        } else {
                            i+=1;
                            if i >= args.len() {
                                let long_name = match opt_char {
                                    'b' => "count-by",
                                    'e' => "every",
                                    'd' => "for-duration",
                                    'n' => "num",
                                    'o' => "offset",
                                    'c' => "until-contains",
                                    'r' => "until-error",
                                    'm' => "until-match",
                                    't' => "until-time",
                                    _ => "unknown",
                                };
                                eprint!("error: The argument '--{} <{}>' requires a value but none was supplied\n\nUSAGE:\n    executable [FLAGS] [OPTIONS] [input]...\n\nFor more information try --help\n", long_name, long_name);
                                std::process::exit(1);
                            }
                            val = args[i].clone();
                            j+=1;
                        }
                        match opt_char {
                            'b' => {
                                match parse_float_literal(&val, "count-by") {
                                    Ok(v) => { count_by_val = v; count_by_str = val; }
                                    Err(e) => { eprint!("{}", e); std::process::exit(1); }
                                }
                            }
                            'e' => {
                                match parse_duration_for_error_context(&val, "every") {
                                    Ok(d) => { every_dur = d; }
                                    Err(e) => { eprint!("{}", e); std::process::exit(1); }
                                }
                            }
                            'd' => {
                                match parse_duration_for_error_context(&val, "for-duration") {
                                    Ok(d) => { for_duration = Some(d); }
                                    Err(e) => { eprint!("{}", e); std::process::exit(1); }
                                }
                            }
                            'n' => {
                                if val.starts_with('-') {
                                    eprint!("error: Found argument '{}' which wasn't expected, or isn't valid in this context\n\nUSAGE:\n    executable --num <num>\n\nFor more information try --help\n", val);
                                    std::process::exit(1);
                                }
                                match parse_float_literal(&val, "num") {
                                    Ok(v) => { num = Some(v); }
                                    Err(e) => { eprint!("{}", e); std::process::exit(1); }
                                }
                            }
                            'o' => {
                                match parse_float_literal(&val, "offset") {
                                    Ok(v) => { offset_val = v; }
                                    Err(e) => { eprint!("{}", e); std::process::exit(1); }
                                }
                            }
                            'c' => { until_contains = Some(val); }
                            'r' => {
                                let parsed = val.parse::<i32>().ok();
                                until_error = parsed;
                            }
                            'm' => {
                                match Regex::new(&val) {
                                    Ok(re) => { until_match_regex = Some(re); }
                                    Err(e) => { eprint!("error: Invalid value for '--until-match <until_match>': {}\n", e); std::process::exit(1); }
                                }
                            }
                            't' => {
                                match NaiveDateTime::parse_from_str(&val, "%Y-%m-%d %H:%M:%S") {
                                    Ok(ndt) => { until_time = Some(ndt); }
                                    Err(_) => { eprint!("error: Invalid value for '--until-time <until_time>': timestamp format is invalid\n"); std::process::exit(1); }
                                }
                            }
                            _ => {}
                        }
                        break;
                    }
                    _ => {
                        eprint!("error: Found argument '-{}' which wasn't expected, or isn't valid in this context\n\nUSAGE:\n    executable [FLAGS] [OPTIONS] [input]...\n\nFor more information try --help\n", ch);
                        std::process::exit(1);
                    }
                }
            }
        } else {
            command_parts.push(arg.clone());
        }
        i+=1;
    }

    if help_flag {
        print_help();
        std::process::exit(0);
    }
    if version_flag {
        print_version();
        std::process::exit(0);
    }

    if command_parts.is_empty() {
        println!("No command supplied, exiting.");
        std::process::exit(0);
    }

    let command_str = command_parts.join(" ");

    let mut items: Vec<String> = Vec::new();
    if let Some(fl) = for_list {
        items.extend(fl);
    }
    if stdin_flag {
        let stdin = io::stdin();
        for line_res in stdin.lock().lines() {
            if let Ok(line) = line_res {
                items.push(line);
            }
        }
    }

    let num_iter: Option<u64> = num.map(|v| if v < 0.0 { 0 } else { v.trunc() as u64 });

    let start_time = Instant::now();
    let for_duration_deadline = for_duration.map(|d| start_time + d);
    let until_time_deadline: Option<chrono::DateTime<Utc>> = until_time.map(|ndt| Utc.from_utc_datetime(&ndt));

    let mut total_runs: u64 = 0;
    let mut successes: u64 = 0;
    let mut failures: u64 = 0;
    let mut failure_codes: Vec<i32> = Vec::new();

    let mut first_output: Option<String> = None;
    let mut last_output: Option<String> = None;

    let mut actual_count: u64 = 0;
    let mut timed_out_due_to_duration = false;

    let mut stdout_handle = io::stdout();

    loop {
        if let Some(deadline) = for_duration_deadline {
            if Instant::now() >= deadline {
                timed_out_due_to_duration = true;
                break;
            }
        }
        if let Some(utc_deadline) = until_time_deadline {
            if Utc::now() >= utc_deadline {
                break;
            }
        }
        if let Some(n) = num_iter {
            if total_runs >= n {
                break;
            }
        } else {
            if !items.is_empty() && total_runs >= items.len() as u64 {
                break;
            }
        }

        let item_opt: Option<String> = if !items.is_empty() {
            if (total_runs as usize) < items.len() {
                Some(items[total_runs as usize].clone())
            } else {
                items.last().cloned()
            }
        } else {
            None
        };

        let count_value = offset_val + count_by_val * (actual_count as f64);
        let count_str = format_count_value(&count_by_str, count_value);

        let mut cmd = Command::new("sh");
        cmd.arg("-c");
        cmd.arg(&command_str);
        cmd.env("COUNT", &count_str);
        cmd.env("ACTUALCOUNT", actual_count.to_string());
        if let Some(ref it) = item_opt {
            cmd.env("ITEM", it);
        }
        cmd.env("SHLVL", "0");

        let output_res = cmd.output();
        let (stdout_bytes, stderr_bytes, exit_code): (Vec<u8>, Vec<u8>, i32) = match output_res {
            Ok(out) => {
                let code = out.status.code().unwrap_or(1);
                (out.stdout, out.stderr, code)
            }
            Err(_) => (Vec::new(), Vec::new(), 1),
        };

        let mut combined = Vec::new();
        combined.extend_from_slice(&stdout_bytes);
        combined.extend_from_slice(&stderr_bytes);
        let output_str = String::from_utf8_lossy(&combined).to_string();

        if only_last {
            last_output = Some(output_str.clone());
        } else {
            let _ = stdout_handle.write_all(output_str.as_bytes());
        }

        total_runs += 1;
        if exit_code == 0 {
            successes += 1;
        } else {
            failures += 1;
            failure_codes.push(exit_code);
        }

        let mut should_break = false;
        if let Some(ref contains) = until_contains {
            if output_str.contains(contains) {
                should_break = true;
            }
        }
        if let Some(ref re) = until_match_regex {
            if re.is_match(&output_str) {
                should_break = true;
            }
        }
        if until_success && exit_code == 0 {
            should_break = true;
        }
        if until_fail && exit_code != 0 {
            should_break = true;
        }
        if let Some(expected) = until_error {
            if exit_code == expected {
                should_break = true;
            }
        }
        if until_changes {
            if let Some(first) = &first_output {
                if *first != output_str {
                    should_break = true;
                }
            }
        }
        if until_same {
            if let Some(first) = &first_output {
                if *first == output_str && total_runs > 1 {
                    should_break = true;
                }
            }
        }

        if first_output.is_none() {
            first_output = Some(output_str);
        }

        if should_break {
            break;
        }

        let will_continue = {
            let mut cont = true;
            if let Some(n) = num_iter {
                if total_runs >= n { cont = false; }
            } else if !items.is_empty() && total_runs >= items.len() as u64 {
                cont = false;
            }
            cont
        };
        if will_continue && every_dur > Duration::from_nanos(0) {
            thread::sleep(every_dur);
        }

        actual_count += 1;
    }

    if only_last {
        if let Some(last) = last_output {
            let _ = stdout_handle.write_all(last.as_bytes());
        }
    }

    if summary {
        let _ = writeln!(stdout_handle, "Total runs:\t{}", total_runs);
        let _ = writeln!(stdout_handle, "Successes:\t{}", successes);
        if failures == 0 {
            let _ = writeln!(stdout_handle, "Failures:\t0");
        } else {
            let codes_str = failure_codes.iter().map(|c| c.to_string()).collect::<Vec<_>>().join(", ");
            let _ = writeln!(stdout_handle, "Failures:\t{} ({})", failures, codes_str);
        }
    }

    let _ = stdout_handle.flush();

    if timed_out_due_to_duration && error_duration {
        std::process::exit(124);
    } else {
        std::process::exit(0);
    }
}
